@module editCursor  src=editCursor.lua  loc=908  mode=chunk  self=ec
@deps grid, cm, cmgr, rowPerBar, logPerRow, moveHook, groupBridge

# Invariants & contracts
  @invariant  cursor (row, col, stop); stop indexes col.stopPos (char-offset), not parts  @ 3
  @invariant  cursorRow is 0-indexed; cursorCol/cursorStop are 1-indexed (Lua-array)  @ 4
  @invariant  ec owns caret/selection/clipboard; no MIDI state — mutations go via tm/cm  @ 5
  @invariant  selection = anchor (fixed) + cursor (moving); sel is the resolved rect  @ 6
  @invariant  sel == nil iff no selection  @ 7
  @invariant  region()'s cursor-degenerate fallback is callsite policy, not stored  @ 8
  @invariant  hBlockScope ∈ {0=free, 1=col, 2=channel, 3=all-cols}  @ 9
  @invariant  vBlockScope ∈ {0=free, 1=beat, 2=bar×vBlockBars, 3=all-rows}; scopes are orthogonal  @ 10
  @invariant  sticky == any nonzero scope; moves under sticky update sel, never clear  @ 11
  @invariant  hBlock=2/3 use part1=part2='*'; selectionStopSpan falls through to whole-col  @ 12
  @invariant  parts within a col order by col.partStart, not stop (parts may be multi-stop)  @ 13
  @invariant  moveHook fires after every position change (paired with clampPos)  @ 14
  @invariant  sel.part1/part2 are part names, or '*' sentinel under hBlock=2/3  @ 16
  @invariant  clip.single.parts = the parts the span covered, in column order  @ 19
  @contract  derives col parts from type/showDelay/trackerMode; pitchWidth,octaveWidth size pitch  @ 870
  @contract  col.showCents widens the pitch field's advance by the readout, addressing no stop  @ 871
  @invariant  ec is the sole writer of col.{parts, stopPos, partAt, partStart, width}  @ 872
  @invariant  pitchWidth >= 1 (name) + octaveWidth, so the name stop never collides with the octave  @ 873

# Shapes
  @shape  selection = { row1, row2, col1, col2, part1, part2 }  -- inclusive both axes  @ 15
  @shape  selAnchor = { row, col, stop }  -- fixed end of an active selection  @ 17
  @shape  clip.single = { mode='single', parts, numRows, events=[clipEvent,...] }  @ 18
  @shape  clip.multi  = { mode='multi', numRows, startType, cols=[clipColEntry,...] }  @ 20
  @shape  clipColEntry = { type, chanDelta, key, events=[clipEvent,...] }  @ 21
  @shape  clipEvent = source-event minus CLIP_RESERVED, plus { row, [endRow] }  @ 23

# Imports
  @require util = 'util'  @ 25
      @invariant  clipColEntry.key: note→lane-pos, cc→cc#, nil for singletons  @ 22
      @invariant  clipEvent.row is 0-relative to clip top  @ 24

