  @state cursorRow, cursorCol, cursorStop = 0, 1, 1  @ 39
  @state hBlockScope, vBlockScope = 0, 0  @ 40
  @state vBlockBars = 1  @ 41   -- bars spanned when vBlockScope == 2
  @state sel, selAnchor  @ 42
  @state regionCursor  @ 46   -- { groupId, instId } | nil
  @state regionScope, regionPushed  @ 47
  @state ec = {}  @ 346
