# Private functions
  -- Position
  @fn clampPos()  @ 53-61
      @contract  clamps to grid extents; idempotent; stop is bound to the current col's stopPos  @ 51
      @invariant  col-changes must precede stop reads (stop is clamped against the current col)  @ 52
  -- Parts
  @fn partAt(col, stop)  @ 65-68
  @fn cursorPart()  @ 70
  @fn firstStopForPart(col, part)  @ 73-80
      @contract  returns first stop whose partAt name matches; caret lands on part-leading char  @ 72
  -- Selection
  @fn isSticky()  @ 84
  @fn selStart()  @ 87-91
      @contract  pins anchor at cursor and produces a 1x1 sel; precondition for selUpdate  @ 86
  @fn selUpdate()  @ 95-134
      @contract  recomputes sel from anchor + cursor + scopes; no-op if selAnchor is nil  @ 93
      @invariant  vBlock=1/2 snap rows to beat/bar; hBlock=2/3 expand cols to channel/all  @ 94
  @fn selClear()  @ 137-140
      @contract  drops sel + anchor + sticky scopes; the only sticky-clear besides unstick()  @ 136
  @fn cycleHBlock()  @ 143-155
      @contract  seeds anchor on first engage; cycles channel→all-cols→col  @ 142
  @fn cycleVBlock()  @ 158-171
      @contract  seeds anchor on first engage; beat→bar, each press grows by a bar; no-op on empty grid  @ 157
  @fn selectAll()  @ 174-179
      @contract  whole grid — both axes to their all-of-axis scope; anchor parks at the caret  @ 173
  @fn swapEnds()  @ 183-194
      @contract  swaps anchor↔cursor on scope-unlocked axes; no-op without a selection  @ 181
      @invariant  swapEnds: vBlock<1 swaps row; hBlock<2 swaps col+stop  @ 182
  -- Movement
  @fn moveRow(n, selecting)  @ 199-206
      @contract  selecting or sticky extends sel; else clears; clamps top/bottom, no wrap  @ 198
  @fn moveStop(n, selecting)  @ 210-236
      @contract  walks stops within col, crossing into the adjacent col at the boundary  @ 208
      @contract  no wrap at first/last col; hBlock≥2 collapses scope to 1 and re-anchors  @ 209
  @fn moveUnit(n, toFirstStop, toLastStop)  @ 239-259
  @fn moveCol(n)  @ 262-278
      @contract  jumps one col, landing on first/last stop; sticky extends/contracts 1 col  @ 261
  @fn moveChannel(n)  @ 282-308
      @contract  jumps one channel; non-sticky lands on first note col (skipping pc/pb)  @ 280
      @contract  sticky preserves the raw chan-edge land  @ 281
  -- Regions (group authoring mode)
  @fn gmgr()  @ 315
      -- All group geometry/persistence is gm's, reached through the bridge
      -- (trackerView's grid<->logical surface). ec never touches gm directly.
  @fn orderedInstances()  @ 319-327
      -- gm:eachInstance iterates pairs(); sort to a stable (groupId, instId)
      -- order so next/prev cycle deterministically.
  @fn cursorIndex(list)  @ 329-335
  @fn currentEntry()  @ 337-342
  -- Position
  -- Part & Region
  -- Motion
  @fn selectSpan(scope, col, stop1, stop2)  @ 470-475
  -- Region mode (group authoring)
  @fn sealMove()  @ 507-524
      -- Commit the pending drag (row + channel + lane): clear swept-onto cells,
      -- re-anchor (gm relanes via del+add, withholds off-take), flush. Verbs seal first.
  @fn exitMode()  @ 526-531
  @fn enterArmed()  @ 533-537
  @fn newFromSelection()  @ 539-547
  @fn stampAt(anchor)  @ 551-557
      -- Clear before staging (gm re-places its own concretes only); stamp a fresh
      -- instance, advance the border. Shared by paste-at-caret and cascade-duplicate.
  @fn newInstance()  @ 559
  @fn duplicate()  @ 563-569
      -- Cascade: the copy lands one group-length past the armed instance and
      -- the border advances onto it, so repeats lay a run hands-free.
  @fn dropInstance()  @ 571-580
  @fn moveBy(rowDelta)  @ 584-595
      -- A nudge accumulates moveDelta and tracks the caret; gm/tm are untouched
      -- until sealMove. Top pinned at row 0; bottom hangs (gm withholds off-take).
  @fn moveByChan(chanStep)  @ 599-613
      -- Channel sibling of moveBy: chanDelta clamped so every member channel stays in 1..16
      -- (no hang-off). moveChannel rides caret + fires hook; lane is preserved by moveInstance.
  @fn noteLanesIn(chan)  @ 617-625
      -- Walk a single-channel all-notes instance sideways one lane per step,
      -- spilling the whole block into the next channel's edge -- shiftEvents' wrap.
  @fn topLaneIn(chan)  @ 627-633
  @fn blockKeys(rect)  @ 635-643
  @fn blockFits(keys, chan, total)  @ 645-651
  @fn laneWalkable(rect)  @ 653-661
  @fn caretToBlock(cur, keys)  @ 664-674
      -- Caret rides the block's lowest realised lane column at the pending position.
  @fn moveByLane(step)  @ 678-708
      -- Lane sibling of moveByChan: accumulate laneDelta (channel-spill at the
      -- boundary) + caret tracking; gm/tm untouched until sealMove.
  @fn shiftSideways(step)  @ 712-715
      -- eventShiftLeft/Right dispatch (mirrors shiftEvents' note-vs-other split):
      -- single-channel all-notes walks lanes; else channel-move (3a).
  @fn resizeBy(edits)  @ 717-721
  @fn paintCell(on)  @ 723-728
  -- Group-instance hop (editing mode)
  @fn hopInstance(step)  @ 783-801
      -- [ / ] in normal editing jump the caret to the same row offset in the
      -- prev/next instance of the group it sits inside. Column is left as-is:
      -- "same place" is the relative row; chasing the stream across instances
      -- on different channels would be a non-linear column remap, out of scope
      -- for this verb. The border feedback is the rendering layer's.
  -- Commands
  -- Decoration
  @fn partsFor(type, showDelay, trackerMode)  @ 854-868
      -- One char of separator between adjacent parts in the rendered cell.

